{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Bucket Public Access Block Missing",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have a public access block configured, which risks accidental exposure of data to the internet if bucket policies or ACLs are misconfigured."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket Encryption Not Configured",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket lacks server-side encryption configuration. While AWS encrypts new objects by default with SSE-S3, explicit configuration (preferably with KMS) is required for compliance and control over encryption keys."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Disabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not enabled, preventing visibility into who accessed the bucket and what actions were taken, which hinders security auditing and incident response."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket Versioning Disabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the bucket, meaning accidental deletions or overwrites cannot be recovered, leading to potential data loss."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "data" {
  bucket        = "${local.resource_prefix.value}-data"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-data"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket = aws_s3_bucket.data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data" {
  bucket = aws_s3_bucket.data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "data" {
  bucket = aws_s3_bucket.data.id

  target_bucket = aws_s3_bucket.data.id # In production, this should point to a dedicated log bucket
  target_prefix = "log/"
}

resource "aws_s3_bucket_versioning" "data" {
  bucket = aws_s3_bucket.data.id
  versioning_configuration {
    status = "Enabled"
  }
}",
  "fix_summary": "Added `aws_s3_bucket_public_access_block` to prevent public exposure, `aws_s3_bucket_server_side_encryption_configuration` to enforce KMS encryption, `aws_s3_bucket_logging` to enable access logs, and `aws_s3_bucket_versioning` to protect against data loss. Note: The logging target currently points to itself for syntactic validity; in a real environment, this should reference a separate, secured log bucket."
}
